1	# gate-functions.sh: the shell functions of the gate's summary and of its ladder comparison.
2	#
3	#   gate_summary <log-dir> <out-file> [machine-label]
4	#                         writes summary.txt: one row per suite from the plain-formatter files under
5	#                         $FORTRESS_HOME/ProjectFortress/TEST-RESULTS/, then the BUILD and Total time
6	#                         lines of <log-dir>/{compileAll,testFast,testSystem,testSpecData}.txt, then
7	#                         "# machine " lines from machine.sh with the label (default "gate")
8	#   gate_compare <last-landed-summary> <this-summary>
9	#                         prints the red lines (RED, EMPTY, COUNT DOWN, SUITE GONE), exit 1 if any;
10	#                         the system-<i> rows are one suite split by sorted index, compared by their sum
11	#   last_landed_summary   prints the path of the newest landed summary.txt
12	#   ladder_filter <file>  masks the "Operation took" time of a ladder run's output
13	#   ladder_compare <baseline-dir> <now-dir>
14	#                         one DOWN, UP, NEW, MISSING or STDOUT line per ladder file that moved
15	#   mg_phases <microgpt-phase.md>
16	#                         one "component<TAB>phase" line per row of the microGPT phase table
17	#
18	# Source it from the tree's root, with FORTRESS_HOME set to that root, in the same Bash call that uses
19	# the functions, since each call starts a new shell:
20	#
21	#     source explorations/coordinator/tools/gate-functions.sh
22	#
23	# It defines the functions and runs nothing. The batch script's gate role
24	# (explorations/coordinator/climb-batch-workflow.js, steps 5 and 7) sources it, and so can any gate run
25	# by hand (the fortress-repo skill's gate.md). Until 2026-10-10 the functions were strings of the batch
26	# script, and the skill extracted them with node and awk (explorations/reviews/skills-agenda-audit.md,
27	# finding GA2).
28	
29	gate_summary () {
30	    local L="$1" O="$2" R="$FORTRESS_HOME/ProjectFortress/TEST-RESULTS" f
31	    {
32	      printf '#suite\ttests\tfailures\terrors\tskipped\n'
33	      for f in "$R"/fast-*/TEST-*.txt "$R"/system-*/TEST-*.txt "$R"/TEST-*SpecDataJUTest.txt ; do
34	        [ -f "$f" ] || continue
35	        awk -v track="$(case "$(basename "$(dirname "$f")")" in TEST-RESULTS) echo specdata ;; *) basename "$(dirname "$f")" ;; esac)" -F'[ ,:]+' '
36	          /^Testsuite:/ { n = split($2, p, "."); s = p[n] }
37	          /^Tests run:/ { print track "/" s "\t" $3 "\t" $5 "\t" $7 "\t" $9 ; exit }' "$f"
38	      done | sort
39	      for f in compileAll testFast testSystem testSpecData ; do
40	        [ -f "$L/$f.txt" ] && grep -h '^BUILD \|^Total time:' "$L/$f.txt" | sed "s|^|# $f: |"
41	      done
42	      bash explorations/compile-ladder/rung-flat-tower/machine.sh "${3:-gate}" | sed 's|^|# machine |'
43	    } > "$O"
44	}
45	
46	gate_compare () {
47	    awk -F'\t' '
48	      function key(s) { sub("^system-[0-9]+/", "system/", s) ; return s }
49	      FNR == NR { if ($0 !~ /^#/ && NF == 5) base[key($1)] += $2 ; next }
50	      $0 !~ /^#/ && NF == 5 {
51	          k = key($1) ; seen[k] = 1 ; cur[k] += $2
52	          if ($3 + 0 > 0 || $4 + 0 > 0)              { print "RED\t" $1 "\t" $3 " failures, " $4 " errors" ; bad++ }
53	          if ($2 + 0 == 0)                           { print "EMPTY\t" $1 ; bad++ }
54	      }
55	      END { for (k in cur) if ((k in base) && cur[k] < base[k]) { print "COUNT DOWN\t" k "\t" base[k] " -> " cur[k] ; bad++ }
56	            for (s in base) if (!(s in seen)) { print "SUITE GONE\t" s "\t" base[s] " -> absent" ; bad++ }
57	            if (bad) exit 1 }' "$1" "$2"
58	}
59	
60	last_landed_summary () {
61	    git -C "$FORTRESS_HOME" log --name-only --pretty=format: -- \
62	        'explorations/compile-ladder/gate-baseline/summary.txt' \
63	        'explorations/compile-ladder/climb-batch-*/gate/summary.txt' | grep -m1 'summary.txt$'
64	}
65	
66	ladder_filter () { sed -E 's/Operation took [0-9.]+ms/Operation took <time>ms/' "$1" ; }
67	
68	ladder_compare () {
69	    local B="$1" N="$2" key
70	    awk -F'\t' '
71	      function rank(p,   r) { r["parse"]=1; r["disambiguate"]=2; r["typecheck"]=3; r["codegen"]=4;
72	                              r["link"]=5; r["run"]=6; r["pass"]=7; return r[p] + 0 }
73	      FNR == NR { if (FNR > 1) b[$1 "/" $2] = $4 ; next }
74	      FNR > 1 {
75	          k = $1 "/" $2
76	          if (!(k in b))                  { print "NEW\t" k "\t" $4 ; next }
77	          if (rank($4) < rank(b[k]))      { print "DOWN\t" k "\t" b[k] " -> " $4 }
78	          else if (rank($4) > rank(b[k])) { print "UP\t" k "\t" b[k] " -> " $4 }
79	      }' "$B/ladder.tsv" "$N/ladder.tsv"
80	    tail -n +2 "$B/pass-list.txt" | cut -f1 | while IFS= read -r key ; do
81	        [ -n "$key" ] || continue
82	        if [ ! -f "$N/raw/$key.run" ] ; then printf 'MISSING\t%s\n' "$key" ; continue ; fi
83	        if ! diff -q <(ladder_filter "$B/raw/$key.run") <(ladder_filter "$N/raw/$key.run") >/dev/null ; then
84	            printf 'STDOUT\t%s\n' "$key"
85	            diff <(ladder_filter "$B/raw/$key.run") <(ladder_filter "$N/raw/$key.run") | sed 's/^/    /' | head -8
86	        fi
87	    done
88	}
89	
90	mg_phases () { awk -F'|' '/^\| *[0-9]+ *\| *`/ { gsub(/[` ]/, "", $3); gsub(/ /, "", $4); print $3 "\t" $4 }' "$1" ; }

